// class = blueprint
class Student {
  // fields (member variables)
  int roll;
  String name;
  // method
  void setData(int r, String n) {
    roll = r;
    name = n;
  }
  void display() {
    System.out.println(roll + " : " + name);
  }
}

class Main {
  public static void main(String[] a) {
    // 1st object
    Student s1 = new Student();
    s1.setData(1, "Asha");
    // 2nd object
    Student s2 = new Student();
    s2.setData(2, "Bhavesh");
    // each object keeps
    s1.display();
    // its own values
    s2.display();
  }
}

class Main {
  // method with two parameters, returns int
  static int add(int x, int y) {
    // sends result back
    return x + y;
  }

  // returns nothing
  static void greet(String n) {
    System.out.println("Hi " + n);
  }

  static double average(int a, int b) {
    return (a + b) / 2.0;
  }

  public static void main(String[] args) {
    // call + store
    int s = add(7, 5);
    System.out.println("sum = " + s);
    greet("Sunil");
    double av = average(70, 90);
    System.out.println("avg = " + av);
  }
}

class Book {
  String title;
  double price;

  // default constructor
  Book() {
    title = "Java";
    price = 0;
  }

  Book(String title, double price) {
    // this.field = parameter
    this.title = title;
    this.price = price;
  }

  void show() {
    String row = title + " Rs. " + price;
    System.out.println(row);
  }
}

class Main {
  public static void main(String[] a) {
    // default
    Book b1 = new Book();
    // parameterized
    Book b2 = new Book("OOP in Java", 299);
    b1.show();
    b2.show();
  }
}

class Account {
  String name;
  double bal;

  // 1: no args
  Account() {
    name = "Guest";
    bal = 0;
  }
  // 2: one arg
  Account(String name) {
    this.name = name;
    bal = 500;
  }
  // 3: two args
  Account(String name, double bal) {
    this.name = name;
    this.bal = bal;
  }
  void show() {
    System.out.println(name + " -> " + bal);
  }
}

class Main {
  public static void main(String[] a) {
    Account a1 = new Account();
    Account a2 = new Account("Riya");
    Account a3 = new Account("Amit", 5000);
    a1.show();
    a2.show();
    a3.show();
  }
}

class Mobile {
  String model;
  double price;

  Mobile(String model) {
    // field = parameter
    this.model = model;
    this.price = 9999;
  }
  // this() calls another constructor first
  Mobile(String model, double price) {
    // constructor chaining
    this(model);
    this.price = price;
  }
  void update(double price) {
    // field = parameter
    this.price = price;
  }
  Mobile bigger(Mobile o) {
    // return the costlier mobile
    return this.price > o.price ? this : o;
  }
  void show() {
    String row = model + " Rs. " + price;
    System.out.println(row);
  }
}

class Main {
  public static void main(String[] a) {
    Mobile m1 = new Mobile("Note 12");
    Mobile m2 = new Mobile("Galaxy", 21249);
    m1.update(14999);
    m1.show();
    m2.show();
    m1.bigger(m2).show();
  }
}

class Counter {
  // ONE copy for all objects
  static int total = 0;
  // one copy per object
  int id;

  // static block:
  static {
    // runs first
    System.out.println("class loading...");
  }

  Counter() {
    // count every object
    total++;
    id = total;
  }

  // static method:
  static void report() {
    // no object
    System.out.println("total = " + total);
  }
}

class Main {
  public static void main(String[] a) {
    new Counter();
    new Counter();
    Counter c = new Counter();
    System.out.println("c.id = " + c.id);
    // called via class name
    Counter.report();
    System.out.println(Counter.total);
  }
}

class BankAcc {
  // hidden from outside
  private double bal;
  // default: same package
  String owner;
  public String bank = "SBI";

  public void deposit(double amt) {
    if (amt > 0)
      // insiders may change it
      bal = bal + amt;
  }
  // controlled reading
  public double getBal() {
    return bal;
  }
}

class Main {
  public static void main(String[] a) {
    BankAcc ac = new BankAcc();
    ac.owner = "Sunil";
    ac.deposit(1200);
    // rejected by the check
    ac.deposit(-500);
    // ac.bal = 99999;
    // ^ compile error: bal is private
    String ow = ac.owner;
    double bl = ac.getBal();
    System.out.println("owner = " + ow);
    System.out.println("bank = " + ac.bank);
    System.out.println("balance = " + bl);
  }
}

class Calc {
  // same name, different parameter lists
  int add(int a, int b) {
    return a + b;
  }
  int add(int a, int b, int c) {
    return a + b + c;
  }
  double add(double a, double b) {
    return a + b;
  }
}

class Main {
  public static void main(String[] x) {
    Calc c = new Calc();
    System.out.println(c.add(2, 3));
    System.out.println(c.add(2, 3, 4));
    System.out.println(c.add(2.5, 3.5));
  }
}

